package com.bablo.app

/*
 * ██████  БУРМАЛДА-67  ██████
 *
 * 64-битный процессор, его ассемблер и программа на этом ассемблере — майнер бабла.
 *
 * Регистры R0..R7, стек на 1024 слова, 65 536 слов памяти данных, флаги сравнения.
 * Proof-of-БАБЛО: программа перебирает nonce, гоняет его через 8 раундов хэша
 * (раунд выбирается по таблице из тысяч уникальных подпрограмм) и сообщает в порт 1,
 * когда хэш делится на 67. Игра за каждый такой блок платит баблом и считает знак π.
 *
 * Синтаксис ассемблера:
 *   ; комментарий            .equ ИМЯ значение
 *   метка:                   DATA v1, v2, ...   (числа, метки, имена .equ)
 *   MOV R0, 67 / MOV R0, R1  LD R1, [R2] / LD R1, [0]   ST [R2], R1
 *   ADD SUB MUL DIV MOD AND OR XOR SHL SHR CMP
 *   JMP JZ JNZ JL JG JLE JGE CALL метка   CALLR R4   RET   PUSH R1   POP R1
 *   OUT порт, R0   NOP   HLT
 */

object BurmaldaOp {
    const val NOP = 0
    const val MOV = 1
    const val ADD = 2
    const val SUB = 3
    const val MUL = 4
    const val DIV = 5
    const val MOD = 6
    const val AND = 7
    const val OR = 8
    const val XOR = 9
    const val SHL = 10
    const val SHR = 11
    const val CMP = 12
    const val JMP = 13
    const val JZ = 14
    const val JNZ = 15
    const val JL = 16
    const val JG = 17
    const val JLE = 18
    const val JGE = 19
    const val CALL = 20
    const val CALLR = 21
    const val RET = 22
    const val PUSH = 23
    const val POP = 24
    const val LD = 25
    const val ST = 26
    const val OUT = 27
    const val HLT = 28

    val NAMES = listOf(
        "NOP", "MOV", "ADD", "SUB", "MUL", "DIV", "MOD", "AND", "OR", "XOR", "SHL", "SHR", "CMP",
        "JMP", "JZ", "JNZ", "JL", "JG", "JLE", "JGE", "CALL", "CALLR", "RET", "PUSH", "POP", "LD", "ST", "OUT", "HLT",
    )
}

/** Собранная программа: инструкции разложены по массивам, чтобы эмулятор летал. */
class BurmaldaProgram(
    val ops: IntArray,
    val a: IntArray,
    val b: LongArray,
    val bReg: BooleanArray,
    val text: Array<String>,
    val data: LongArray,
    val sourceLines: Int,
) {
    val size get() = ops.size
}

class BurmaldaAsmException(line: Int, message: String) : Exception("строка $line: $message")

/** Двухпроходный ассемблер БУРМАЛДА-67. */
object BurmaldaAsm {
    const val MEM_SIZE = 1 shl 16
    /** Адреса 0..15 — порты ввода-вывода игры, данные программы начинаются с 16. */
    const val DATA_START = 16

    private class Line(val no: Int, val op: String, val args: List<String>, val text: String)

    fun assemble(source: String): BurmaldaProgram {
        val codeLabels = HashMap<String, Int>()
        val dataLabels = HashMap<String, Int>()
        val equ = HashMap<String, Long>()
        val code = ArrayList<Line>()
        val dataLines = ArrayList<Line>()
        val pending = ArrayList<String>()
        var dataPtr = DATA_START
        var lines = 0

        // Проход 1: метки, .equ, раскладка кода и данных.
        source.lineSequence().forEachIndexed { i, raw ->
            lines++
            var s = raw.substringBefore(';').trim()
            while (true) {
                val colon = s.indexOf(':')
                if (colon <= 0 || !s.substring(0, colon).all { it.isLetterOrDigit() || it == '_' }) break
                pending += s.substring(0, colon)
                s = s.substring(colon + 1).trim()
            }
            if (s.isEmpty()) return@forEachIndexed
            val op = s.substringBefore(' ').uppercase()
            val rest = s.substringAfter(' ', "").trim()
            val args = if (rest.isEmpty()) emptyList() else rest.split(',').map { it.trim() }
            when (op) {
                ".EQU" -> {
                    val parts = rest.split(Regex("\\s+"))
                    if (parts.size != 2) throw BurmaldaAsmException(i + 1, ".equ ИМЯ значение")
                    equ[parts[0]] = parseNumber(parts[1]) ?: throw BurmaldaAsmException(i + 1, "не число: ${parts[1]}")
                }
                "DATA" -> {
                    pending.forEach { dataLabels[it] = dataPtr }
                    pending.clear()
                    dataLines += Line(i + 1, op, args, s)
                    dataPtr += args.size
                    if (dataPtr > MEM_SIZE) throw BurmaldaAsmException(i + 1, "данные не влезли в память")
                }
                else -> {
                    pending.forEach { codeLabels[it] = code.size }
                    pending.clear()
                    code += Line(i + 1, op, args, s)
                }
            }
        }

        fun value(line: Line, t: String): Long = parseNumber(t) ?: equ[t]
            ?: codeLabels[t]?.toLong() ?: dataLabels[t]?.toLong()
            ?: throw BurmaldaAsmException(line.no, "не знаю, что такое «$t»")

        fun reg(line: Line, t: String): Int {
            val r = regIndex(t) ?: throw BurmaldaAsmException(line.no, "ожидался регистр R0..R7, а тут «$t»")
            return r
        }

        // Проход 2: кодирование.
        val n = code.size
        val ops = IntArray(n)
        val a = IntArray(n)
        val b = LongArray(n)
        val bReg = BooleanArray(n)
        val text = Array(n) { code[it].text }
        code.forEachIndexed { pc, line ->
            val opc = BurmaldaOp.NAMES.indexOf(line.op)
            if (opc < 0) throw BurmaldaAsmException(line.no, "неизвестная инструкция ${line.op}")
            ops[pc] = opc
            fun need(k: Int) {
                if (line.args.size != k) throw BurmaldaAsmException(line.no, "${line.op} ждёт аргументов: $k")
            }
            fun src(t: String) {
                val r = regIndex(t)
                if (r != null) {
                    bReg[pc] = true
                    b[pc] = r.toLong()
                } else {
                    b[pc] = value(line, t)
                }
            }
            fun addr(t: String) {
                if (!t.startsWith("[") || !t.endsWith("]")) throw BurmaldaAsmException(line.no, "ожидался адрес в [скобках]")
                src(t.substring(1, t.length - 1).trim())
            }
            when (opc) {
                BurmaldaOp.NOP, BurmaldaOp.RET, BurmaldaOp.HLT -> need(0)
                BurmaldaOp.JMP, BurmaldaOp.JZ, BurmaldaOp.JNZ, BurmaldaOp.JL, BurmaldaOp.JG,
                BurmaldaOp.JLE, BurmaldaOp.JGE, BurmaldaOp.CALL -> {
                    need(1)
                    b[pc] = codeLabels[line.args[0]]?.toLong()
                        ?: throw BurmaldaAsmException(line.no, "нет такой метки кода: ${line.args[0]}")
                }
                BurmaldaOp.CALLR, BurmaldaOp.PUSH, BurmaldaOp.POP -> {
                    need(1)
                    a[pc] = reg(line, line.args[0])
                }
                BurmaldaOp.LD -> {
                    need(2)
                    a[pc] = reg(line, line.args[0])
                    addr(line.args[1])
                }
                BurmaldaOp.ST -> {
                    need(2)
                    addr(line.args[0])
                    a[pc] = reg(line, line.args[1])
                }
                BurmaldaOp.OUT -> {
                    need(2)
                    b[pc] = value(line, line.args[0])
                    a[pc] = reg(line, line.args[1])
                }
                else -> {
                    need(2)
                    a[pc] = reg(line, line.args[0])
                    src(line.args[1])
                }
            }
        }

        val data = LongArray(MEM_SIZE)
        var p = DATA_START
        dataLines.forEach { line -> line.args.forEach { data[p++] = value(line, it) } }

        return BurmaldaProgram(ops, a, b, bReg, text, data, lines)
    }

    private fun regIndex(t: String): Int? =
        if (t.length == 2 && (t[0] == 'R' || t[0] == 'r') && t[1] in '0'..'7') t[1] - '0' else null

    private fun parseNumber(t: String): Long? = when {
        t.startsWith("0x") || t.startsWith("0X") -> t.substring(2).toULongOrNull(16)?.toLong()
        t.startsWith("-0x") -> t.substring(3).toULongOrNull(16)?.toLong()?.let { -it }
        else -> t.toLongOrNull()
    }
}

/** Сам процессор. Выполняет программу по тактам, OUT отдаёт наружу через [onOut]. */
class BurmaldaCpu(val program: BurmaldaProgram) {
    val r = LongArray(8)
    val mem: LongArray = program.data.copyOf()
    private val stack = LongArray(1024)
    var sp = 0
        private set
    var pc = 0
        private set
    var cycles = 0L
        private set
    var fault: String? = null
        private set
    val halted get() = fault != null

    /** -1, 0, 1 — результат последнего CMP (или знак результата арифметики). */
    private var flag = 0

    var onOut: (port: Long, value: Long) -> Unit = { _, _ -> }

    val currentText: String get() = if (pc in 0 until program.size) program.text[pc] else "—"

    private fun crash(why: String) {
        fault = "$why (PC=$pc)"
    }

    /** Выполняет до [budget] инструкций. */
    fun run(budget: Int) {
        val ops = program.ops
        val aa = program.a
        val bb = program.b
        val isReg = program.bReg
        var left = budget
        while (left > 0 && fault == null) {
            if (pc !in ops.indices) {
                crash("PC улетел за программу")
                break
            }
            val i = pc
            val op = ops[i]
            val a = aa[i]
            val v = if (isReg[i]) r[bb[i].toInt()] else bb[i]
            pc++
            when (op) {
                BurmaldaOp.NOP -> Unit
                BurmaldaOp.MOV -> r[a] = v
                BurmaldaOp.ADD -> r[a] += v
                BurmaldaOp.SUB -> r[a] -= v
                BurmaldaOp.MUL -> r[a] *= v
                BurmaldaOp.DIV -> if (v == 0L) crash("деление на ноль") else r[a] /= v
                BurmaldaOp.MOD -> if (v == 0L) crash("деление на ноль") else r[a] %= v
                BurmaldaOp.AND -> r[a] = r[a] and v
                BurmaldaOp.OR -> r[a] = r[a] or v
                BurmaldaOp.XOR -> r[a] = r[a] xor v
                BurmaldaOp.SHL -> r[a] = r[a] shl (v and 63).toInt()
                BurmaldaOp.SHR -> r[a] = r[a] ushr (v and 63).toInt()
                BurmaldaOp.CMP -> flag = r[a].compareTo(v).coerceIn(-1, 1)
                BurmaldaOp.JMP -> pc = bb[i].toInt()
                BurmaldaOp.JZ -> if (flag == 0) pc = bb[i].toInt()
                BurmaldaOp.JNZ -> if (flag != 0) pc = bb[i].toInt()
                BurmaldaOp.JL -> if (flag < 0) pc = bb[i].toInt()
                BurmaldaOp.JG -> if (flag > 0) pc = bb[i].toInt()
                BurmaldaOp.JLE -> if (flag <= 0) pc = bb[i].toInt()
                BurmaldaOp.JGE -> if (flag >= 0) pc = bb[i].toInt()
                BurmaldaOp.CALL, BurmaldaOp.CALLR -> {
                    if (sp >= stack.size) crash("переполнение стека") else {
                        stack[sp++] = pc.toLong()
                        pc = if (op == BurmaldaOp.CALL) bb[i].toInt() else r[a].toInt()
                    }
                }
                BurmaldaOp.RET -> if (sp == 0) crash("RET с пустым стеком") else pc = stack[--sp].toInt()
                BurmaldaOp.PUSH -> if (sp >= stack.size) crash("переполнение стека") else stack[sp++] = r[a]
                BurmaldaOp.POP -> if (sp == 0) crash("POP с пустым стеком") else r[a] = stack[--sp]
                BurmaldaOp.LD -> if (v !in 0 until mem.size) crash("LD мимо памяти") else r[a] = mem[v.toInt()]
                BurmaldaOp.ST -> if (v !in 0 until mem.size) crash("ST мимо памяти") else mem[v.toInt()] = r[a]
                BurmaldaOp.OUT -> onOut(bb[i], r[a])
                BurmaldaOp.HLT -> crash("HLT")
            }
            if (op in BurmaldaOp.ADD..BurmaldaOp.SHR) flag = r[a].compareTo(0L).coerceIn(-1, 1)
            cycles++
            left--
        }
    }
}

/** Порты майнера (совпадают с .equ в программе). */
