private fun burmaldaAsm0(): String = """
; ================================================================
; БУРМАЛДА-67 — майнер бабла (Proof-of-БАБЛО)
; Игра кладёт стартовый nonce в [0]. Каждый nonce проходит 8 раундов хэша:
; номер раунда берётся из самого хэша, адрес — из таблицы rounds.
; Если хэш делится на 67 — блок найден, пишем его в порт 1.
; ================================================================
.equ NONCE 0
.equ ROUNDS 6531
.equ PASSES 8
.equ DIFFICULTY 67
.equ PORT_BLOCK 1
.equ PORT_NONCE 2

start:
    LD    R1, [NONCE]       ; откуда продолжаем
mine:
    ADD   R1, 1             ; следующий nonce
    ST    [NONCE], R1       ; игра сохраняет прогресс отсюда
    MOV   R0, R1
    XOR   R0, 0x6767676767676767
    MOV   R2, 0             ; номер прохода
pass:
    MOV   R3, R0
    SHR   R3, 11
    XOR   R3, R2
    MOD   R3, ROUNDS        ; какой раунд крутим
    ADD   R3, rounds        ; адрес в таблице
    LD    R4, [R3]
    PUSH  R1
    CALLR R4
    POP   R1
    ADD   R2, 1
    CMP   R2, PASSES
    JL    pass
    OUT   PORT_NONCE, R1
    MOV   R5, R0
    SHR   R5, 1             ; беззнаковый хэш
    MOD   R5, DIFFICULTY
    CMP   R5, 0
    JNZ   mine              ; не делится на 67 — дальше
    OUT   PORT_BLOCK, R0    ; БЛОК! бабло игроку
    JMP   mine

; ================================================================
; Раунды хэша. Все разные, все реально вызываются.
; ================================================================

; --- раунд 0 ---
round_0:
    MOV   R6, R0
    SHR   R6, 42
    MUL   R6, 0x1DB84AA91325AF11
    XOR   R0, R6
    SUB   R0, 0x688BF8CAC4189FCD
    XOR   R0, R2
    RET

; --- раунд 1 ---
round_1:
    MUL   R0, 0x98AAC605F1E366B1
    MOV   R6, R0
    SHR   R6, 30
    XOR   R0, R6
    ADD   R0, 0x7CDFB92B6DF1823C
    XOR   R0, R2
    RET

; --- раунд 2 ---
round_2:
    XOR   R0, 0x08F4F73F49B8FEA6
    MOV   R6, R0
    SHL   R6, 19
    ADD   R0, R6
    MUL   R0, 0x2D40DB9BAA57D4E1
    ADD   R0, R2
    RET

; --- раунд 3 ---
round_3:
    ADD   R0, 0x7DBF51751873E214
    MOV   R6, R0
    SHR   R6, 12
    OR    R6, 1
    MUL   R0, R6
    XOR   R0, R2
    RET

; --- раунд 4 ---
round_4:
    XOR   R0, 0x03414CE29762130C
    MOV   R6, R0
    SHL   R6, 25
    ADD   R0, R6
    MUL   R0, 0xE1B3CD71BF7DEB0F
    ADD   R0, R2
    RET

; --- раунд 5 ---
round_5:
    ADD   R0, 0x5EF361ABF9388C2B
    MOV   R6, R0
    SHR   R6, 5
    OR    R6, 1
    MUL   R0, R6
    XOR   R0, R2
    RET

; --- раунд 6 ---
round_6:
    MUL   R0, 0xBBF53A6BC3A29E4F
    MOV   R6, R0
    SHR   R6, 37
    XOR   R0, R6
    ADD   R0, 0x3BA5E4C5CEFBBDA2
    XOR   R0, R2
    RET

; --- раунд 7 ---
round_7:
    ADD   R0, 0x6F6701C728FE3617
    MOV   R6, R0
    SHR   R6, 24
    OR    R6, 1
    MUL   R0, R6
    XOR   R0, R2
    RET

; --- раунд 8 ---
round_8:
    XOR   R0, 0x22FD4E1406A90649
    MOV   R6, R0
    SHL   R6, 10
    ADD   R0, R6
    MUL   R0, 0x3C5EBEE2597E2453
    ADD   R0, R2
    RET

; --- раунд 9 ---
round_9:
    MOV   R6, R0
    SHR   R6, 38
